import java.math.BigInteger;
import java.math.BigDecimal;

BigInteger a = new BigInteger("9999999999999999999");
BigInteger b = a.multiply(a);
System.out.println(b);

BigDecimal x = new BigDecimal("1.0");
BigDecimal y = new BigDecimal("3.0");
BigDecimal result = x.divide(y, 20, BigDecimal.ROUND_HALF_UP);
System.out.println(result);  // 0.33333333333333333333
